function show<T: Display>(v: T): string
    return v:to_string()
end

function trace<T: Debug>(v: T): string
    return v:debug()
end

function twice<T: Clone>(v: T)
    return v:clone()
end

function same<T: Eq>(a: T, b: T): boolean
    return a:eq(b)
end

function same<T: PartialEq>(a: T, b: T): boolean
    return a:eq(b)
end

function sum<T: Add>(a: T, b: T)
    return a:add(b)
end

function diff<T: Sub>(a: T, b: T)
    return a:sub(b)
end

function scale<T: Mul>(a: T, b: T)
    return a:mul(b)
end

function ratio<T: Div>(a: T, b: T)
    return a:div(b)
end

function to_data<T: Serialize>(v: T): any
    return v:serialize()
end

